# pylint: disable=too-many-lines

"""
SSH configuration and WebSocket bridge for remote development.

This module provides:
1. SSH config generation for remote development tools
2. WebSocket-to-stdio bridge (replacing websocat dependency)

Supported tools:
- VSCode Remote-SSH
- Claude Code
- Cursor
- Codex (OpenAI)

"""

import asyncio
import json
import signal
import subprocess
import sys
from dataclasses import dataclass
from enum import Enum
from pathlib import Path
from typing import Callable, Optional

import requests

# WebSocket library (optional dependency)
try:
    from websockets.asyncio.client import connect as ws_connect

    WEBSOCKETS_AVAILABLE = True
except ImportError:
    WEBSOCKETS_AVAILABLE = False
    ws_connect = None


class RemoteTool(str, Enum):
    """Supported remote development tools."""

    VSCODE = "vscode"
    CLAUDE_CODE = "claude-code"
    CURSOR = "cursor"
    CODEX = "codex"


@dataclass
class SSHConfig:
    """SSH connection configuration."""

    host: str
    hostname: str
    user: str
    port: int = 22
    identity_file: Optional[str] = None
    proxy_command: Optional[str] = None
    strict_host_key_checking: str = "no"
    user_known_hosts_file: str = "/dev/null"

    def to_ssh_config(self) -> str:
        """Generate SSH config file entry."""
        lines = [
            f"Host {self.host}",
            f"    HostName {self.hostname}",
            f"    User {self.user}",
            f"    Port {self.port}",
            f"    StrictHostKeyChecking {self.strict_host_key_checking}",
            f"    UserKnownHostsFile {self.user_known_hosts_file}",
        ]
        if self.identity_file:
            lines.append(f"    IdentityFile {self.identity_file}")
        if self.proxy_command:
            lines.append(f"    ProxyCommand {self.proxy_command}")
        return "\n".join(lines)


@dataclass
class PodConnection:
    """Connection info for a qBraid pod."""

    slug: str
    username: str
    ssh_host: str
    ssh_port: int = 22
    websocket_url: Optional[str] = None
    token: Optional[str] = None

    @property
    def ssh_alias(self) -> str:
        """SSH config alias for this pod."""
        return f"qbraid-{self.slug}"


# =============================================================================
# SSH Config Management
# =============================================================================


def get_ssh_config_path() -> Path:
    """Get path to SSH config file."""
    return Path.home() / ".ssh" / "config"


def get_qbraid_ssh_config_path() -> Path:
    """Get path to qBraid-specific SSH config file."""
    ssh_dir = Path.home() / ".ssh"
    ssh_dir.mkdir(mode=0o700, exist_ok=True)
    return ssh_dir / "config.d" / "qbraid"


def ensure_ssh_include() -> None:
    """Ensure SSH config includes qBraid config file."""
    config_path = get_ssh_config_path()
    qbraid_config = get_qbraid_ssh_config_path()
    include_line = f"Include {qbraid_config}"

    # Ensure parent directory exists
    qbraid_config.parent.mkdir(mode=0o700, parents=True, exist_ok=True)

    # Check if include already exists
    if config_path.exists():
        content = config_path.read_text()
        if include_line in content:
            return
        # Prepend include directive
        new_content = f"{include_line}\n\n{content}"
    else:
        new_content = f"{include_line}\n"

    config_path.write_text(new_content)
    config_path.chmod(0o600)


def add_pod_ssh_config(connection: PodConnection) -> SSHConfig:
    """Add SSH config entry for a pod connection.

    Args:
        connection: Pod connection information.

    Returns:
        SSHConfig object representing the entry.
    """
    config = SSHConfig(
        host=connection.ssh_alias,
        hostname=connection.ssh_host,
        user=connection.username,
        port=connection.ssh_port,
    )

    # Ensure include directive exists
    ensure_ssh_include()

    # Read existing config
    config_path = get_qbraid_ssh_config_path()
    existing_content = ""
    if config_path.exists():
        existing_content = config_path.read_text()

    # Check if host already exists
    if f"Host {config.host}" in existing_content:
        # Remove old entry
        lines = existing_content.split("\n")
        new_lines = []
        skip_until_next_host = False
        for line in lines:
            if line.startswith(f"Host {config.host}"):
                skip_until_next_host = True
                continue
            if skip_until_next_host and line.startswith("Host "):
                skip_until_next_host = False
            if not skip_until_next_host:
                new_lines.append(line)
        existing_content = "\n".join(new_lines)

    # Append new config
    new_content = existing_content.rstrip() + "\n\n" + config.to_ssh_config() + "\n"
    config_path.write_text(new_content.lstrip())
    config_path.chmod(0o600)

    return config


def remove_pod_ssh_config(slug: str) -> bool:
    """Remove SSH config entry for a pod.

    Args:
        slug: Pod slug.

    Returns:
        True if entry was removed, False if not found.
    """
    config_path = get_qbraid_ssh_config_path()
    if not config_path.exists():
        return False

    host_alias = f"qbraid-{slug}"
    content = config_path.read_text()

    if f"Host {host_alias}" not in content:
        return False

    # Remove the entry
    lines = content.split("\n")
    new_lines = []
    skip_until_next_host = False
    for line in lines:
        if line.startswith(f"Host {host_alias}"):
            skip_until_next_host = True
            continue
        if skip_until_next_host and line.startswith("Host "):
            skip_until_next_host = False
        if not skip_until_next_host:
            new_lines.append(line)

    config_path.write_text("\n".join(new_lines))
    return True


def list_pod_ssh_configs() -> list[str]:
    """List all qBraid pod SSH config aliases.

    Returns:
        List of SSH config host aliases (e.g., ["qbraid-my-pod", "qbraid-other"])
    """
    config_path = get_qbraid_ssh_config_path()
    if not config_path.exists():
        return []

    content = config_path.read_text()
    aliases = []
    for line in content.split("\n"):
        if line.startswith("Host qbraid-"):
            alias = line.replace("Host ", "").strip()
            aliases.append(alias)
    return aliases


# =============================================================================
# Tool-Specific Configuration
# =============================================================================


def get_tool_config_path(tool: RemoteTool) -> Optional[Path]:
    """Get the config path for a specific remote tool.

    Args:
        tool: Remote development tool.

    Returns:
        Path to tool's config file, or None if not applicable.
    """
    home = Path.home()

    paths = {
        RemoteTool.VSCODE: home / ".ssh" / "config",  # Uses standard SSH config
        RemoteTool.CLAUDE_CODE: home / ".claude" / "settings.json",
        RemoteTool.CURSOR: home / ".cursor" / "settings.json",
        RemoteTool.CODEX: home / ".codex" / "config.json",
    }
    return paths.get(tool)


def configure_vscode_remote(connection: PodConnection) -> dict:
    """Configure VSCode Remote-SSH for a pod.

    Args:
        connection: Pod connection information.

    Returns:
        Dict with configuration details.
    """
    config = add_pod_ssh_config(connection)
    return {
        "tool": "vscode",
        "ssh_alias": config.host,
        "command": f"code --remote ssh-remote+{config.host} /home/{connection.username}",
        "config_file": str(get_ssh_config_path()),
    }


def configure_cursor_remote(connection: PodConnection) -> dict:
    """Configure Cursor for a pod.

    Args:
        connection: Pod connection information.

    Returns:
        Dict with configuration details.
    """
    config = add_pod_ssh_config(connection)
    return {
        "tool": "cursor",
        "ssh_alias": config.host,
        "command": f"cursor --remote ssh-remote+{config.host} /home/{connection.username}",
        "config_file": str(get_ssh_config_path()),
    }


def configure_claude_code_remote(connection: PodConnection) -> dict:
    """Configure Claude Code for remote SSH.

    Args:
        connection: Pod connection information.

    Returns:
        Dict with configuration details.
    """
    config = add_pod_ssh_config(connection)
    settings_path = get_tool_config_path(RemoteTool.CLAUDE_CODE)

    # Read existing settings
    settings = {}
    if settings_path and settings_path.exists():
        try:
            settings = json.loads(settings_path.read_text())
        except json.JSONDecodeError:
            pass

    # Add/update remote hosts
    if "remoteHosts" not in settings:
        settings["remoteHosts"] = []

    # Check if host already exists
    host_entry = {"name": config.host, "sshHost": config.host}
    existing = [h for h in settings["remoteHosts"] if h.get("name") == config.host]
    if not existing:
        settings["remoteHosts"].append(host_entry)

        # Write settings
        if settings_path:
            settings_path.parent.mkdir(parents=True, exist_ok=True)
            settings_path.write_text(json.dumps(settings, indent=2))

    return {
        "tool": "claude-code",
        "ssh_alias": config.host,
        "command": f"claude --remote {config.host}",
        "config_file": str(settings_path) if settings_path else None,
    }


def configure_remote_tool(tool: RemoteTool, connection: PodConnection) -> dict:
    """Configure a remote development tool for a pod.

    Args:
        tool: Remote development tool to configure.
        connection: Pod connection information.

    Returns:
        Dict with tool-specific configuration details.

    Example:
        >>> conn = PodConnection(
        ...     slug="my-pod",
        ...     username="jovyan",
        ...     ssh_host="ssh-staging.lab.qbraid.com"
        ... )
        >>> config = configure_remote_tool(RemoteTool.VSCODE, conn)
        >>> print(config["command"])
        'code --remote ssh-remote+qbraid-my-pod /home/jovyan'
    """
    configurators = {
        RemoteTool.VSCODE: configure_vscode_remote,
        RemoteTool.CURSOR: configure_cursor_remote,
        RemoteTool.CLAUDE_CODE: configure_claude_code_remote,
        RemoteTool.CODEX: configure_vscode_remote,  # Codex uses SSH config like VSCode
    }
    return configurators[tool](connection)


# =============================================================================
# WebSocket-to-Stdio Bridge (websocat replacement)
# =============================================================================


class WebSocketBridge:
    """Bridge between WebSocket and stdio streams.

    This class replaces the need for the external `websocat` tool by providing
    native Python WebSocket-to-stdio bridging for SSH-over-WebSocket scenarios.

    Example:
        >>> bridge = WebSocketBridge("wss://example.com/ssh?token=abc")
        >>> await bridge.run()  # Bridges stdin/stdout to WebSocket
    """

    def __init__(
        self,
        websocket_url: str,
        on_connect: Optional[Callable[[], None]] = None,
        on_disconnect: Optional[Callable[[], None]] = None,
        on_error: Optional[Callable[[Exception], None]] = None,
        ping_interval: float = 30.0,
        reconnect: bool = False,
    ):
        """Initialize WebSocket bridge.

        Args:
            websocket_url: WebSocket URL to connect to.
            on_connect: Callback when connection established.
            on_disconnect: Callback when connection closed.
            on_error: Callback for errors.
            ping_interval: Seconds between ping frames.
            reconnect: Whether to auto-reconnect on disconnect.
        """
        if not WEBSOCKETS_AVAILABLE:
            raise ImportError("websockets package required. Install with: pip install websockets")

        self.url = websocket_url
        self.on_connect = on_connect
        self.on_disconnect = on_disconnect
        self.on_error = on_error
        self.ping_interval = ping_interval
        self.reconnect = reconnect
        self._ws = None
        self._running = False
        self._tasks: list[asyncio.Task] = []

    async def _read_stdin(self) -> None:
        """Read from stdin and send to WebSocket."""
        loop = asyncio.get_event_loop()
        reader = asyncio.StreamReader()
        protocol = asyncio.StreamReaderProtocol(reader)
        await loop.connect_read_pipe(lambda: protocol, sys.stdin)

        try:
            while self._running and self._ws:
                data = await reader.read(4096)
                if not data:
                    break
                await self._ws.send(data)
        except Exception as e:
            if self.on_error:
                self.on_error(e)

    async def _write_stdout(self) -> None:
        """Receive from WebSocket and write to stdout."""
        try:
            assert self._ws is not None
            async for message in self._ws:
                if isinstance(message, bytes):
                    sys.stdout.buffer.write(message)
                else:
                    sys.stdout.write(message)
                sys.stdout.flush()
        except Exception as e:
            if self.on_error:
                self.on_error(e)

    async def run(self) -> None:
        """Run the WebSocket bridge.

        This method blocks until the connection is closed or interrupted.
        """
        self._running = True

        # Set up signal handlers
        loop = asyncio.get_event_loop()
        for sig in (signal.SIGINT, signal.SIGTERM):
            loop.add_signal_handler(sig, lambda: asyncio.create_task(self.stop()))

        while self._running:
            try:
                async with ws_connect(self.url, ping_interval=self.ping_interval) as ws:
                    self._ws = ws
                    if self.on_connect:
                        self.on_connect()

                    # Run stdin reader and stdout writer concurrently
                    stdin_task = asyncio.create_task(self._read_stdin())
                    stdout_task = asyncio.create_task(self._write_stdout())
                    self._tasks = [stdin_task, stdout_task]

                    # Wait for either task to complete
                    _done, pending = await asyncio.wait(
                        self._tasks, return_when=asyncio.FIRST_COMPLETED
                    )

                    # Cancel pending tasks
                    for task in pending:
                        task.cancel()
                        try:
                            await task
                        except asyncio.CancelledError:
                            pass

            except Exception as e:
                if self.on_error:
                    self.on_error(e)
                if self.reconnect:
                    await asyncio.sleep(1)  # Brief delay before reconnect

            finally:
                self._ws = None
                if self.on_disconnect:
                    self.on_disconnect()

            if not self.reconnect:
                break

    async def stop(self) -> None:
        """Stop the WebSocket bridge."""
        self._running = False
        if self._ws:
            await self._ws.close()
        for task in self._tasks:
            task.cancel()


async def run_websocket_bridge(
    url: str,
    ping_interval: float = 30.0,
    reconnect: bool = False,
) -> None:
    """Run a WebSocket-to-stdio bridge (websocat replacement).

    This function connects to a WebSocket URL and bridges data between
    the WebSocket and stdin/stdout. Useful for SSH-over-WebSocket scenarios.

    Args:
        url: WebSocket URL to connect to.
        ping_interval: Seconds between ping frames.
        reconnect: Whether to auto-reconnect on disconnect.

    Example:
        >>> import asyncio
        >>> asyncio.run(run_websocket_bridge("wss://example.com/ssh"))
    """
    bridge = WebSocketBridge(url, ping_interval=ping_interval, reconnect=reconnect)
    await bridge.run()


def websocket_bridge_sync(
    url: str,
    ping_interval: float = 30.0,
    reconnect: bool = False,
) -> None:
    """Synchronous wrapper for WebSocket bridge.

    Args:
        url: WebSocket URL to connect to.
        ping_interval: Seconds between ping frames.
        reconnect: Whether to auto-reconnect on disconnect.
    """
    asyncio.run(run_websocket_bridge(url, ping_interval, reconnect))


# =============================================================================
# Convenience Functions
# =============================================================================


def get_ssh_command(connection: PodConnection) -> str:
    """Get SSH command for connecting to a pod.

    Args:
        connection: Pod connection information.

    Returns:
        SSH command string.
    """
    return f"ssh {connection.username}@{connection.ssh_host} -p {connection.ssh_port}"


def get_scp_command(
    connection: PodConnection, local_path: str, remote_path: str, upload: bool = True
) -> str:
    """Get SCP command for file transfer.

    Args:
        connection: Pod connection information.
        local_path: Local file path.
        remote_path: Remote file path.
        upload: If True, upload local to remote. If False, download.

    Returns:
        SCP command string.
    """
    remote = f"{connection.username}@{connection.ssh_host}:{remote_path}"
    port_arg = f"-P {connection.ssh_port}"

    if upload:
        return f"scp {port_arg} {local_path} {remote}"
    return f"scp {port_arg} {remote} {local_path}"


# =============================================================================
# qBraid SSH Proxy Support (jupyter-server-proxy with raw_socket_proxy)
# =============================================================================

# Default qBraid Lab domains
QBRAID_LAB_PRODUCTION = "lab.qbraid.com"
QBRAID_LAB_STAGING = "lab-staging.qbraid.com"

# Default cluster ID
DEFAULT_CLUSTER_ID = "lab"


def get_hub_domain(cluster_id: str = DEFAULT_CLUSTER_ID) -> str:
    """Derive JupyterHub domain from cluster ID.

    Args:
        cluster_id: Cluster identifier (e.g., "lab", "lab-v2-staging").

    Returns:
        Hub domain (e.g., "lab.qbraid.com", "lab-v2-staging.qbraid.com").
    """
    return f"{cluster_id}.qbraid.com"


def get_sshd_proxy_url(
    hub_domain: str,
    username: str,
    use_ssl: bool = True,
) -> str:
    """Get WebSocket URL for qBraid SSH proxy.

    The SSH proxy is exposed via jupyter-server-proxy at the /sshd/ path.
    This uses raw_socket_proxy for direct SSH protocol tunneling over WebSocket.

    Args:
        hub_domain: JupyterHub domain (e.g., "lab.qbraid.com").
        username: JupyterHub username (email).
        use_ssl: Whether to use wss:// (default: True).

    Returns:
        WebSocket URL for SSH proxy.

    Example:
        >>> url = get_sshd_proxy_url("lab.qbraid.com", "user@email.com")
        >>> print(url)
        'wss://lab.qbraid.com/user/user@email.com/sshd/'
    """
    protocol = "wss" if use_ssl else "ws"
    return f"{protocol}://{hub_domain}/user/{username}/sshd/"


def get_proxy_command(
    hub_domain: str,
    username: str,
    token: str,
    use_websocat: bool = False,
) -> str:
    """Get SSH ProxyCommand for qBraid SSH proxy.

    This returns a ProxyCommand that can be used in SSH config to connect
    through the qBraid SSH proxy WebSocket endpoint. By default, it uses
    the native Python WebSocket bridge, but can optionally use websocat.

    Args:
        hub_domain: JupyterHub domain.
        username: JupyterHub username (email).
        token: JupyterHub API token.
        use_websocat: If True, use websocat instead of native Python bridge.

    Returns:
        ProxyCommand string for SSH config.

    Example:
        >>> cmd = get_proxy_command("lab.qbraid.com", "user@example.com", "token123")
        >>> # Returns command using native Python bridge
    """
    url = get_sshd_proxy_url(hub_domain, username, use_ssl=True)

    if use_websocat:
        return f'websocat --binary -H="Authorization: token {token}" ' f"asyncstdio: {url}"

    # Use native Python WebSocket bridge (replaces websocat)
    python_path = sys.executable or "python3"
    return (
        f"{python_path} -W ignore::RuntimeWarning -m qbraid_core.services.compute.ssh bridge "
        f'"{url}" --token "{token}"'
    )


def generate_sshd_proxy_config(
    hub_domain: str,
    username: str,
    token: str,
    host_alias: Optional[str] = None,
    ssh_user: str = "jovyan",
    identity_file: Optional[str] = None,
) -> SSHConfig:
    """Generate SSH config for qBraid SSH proxy connection.

    Args:
        hub_domain: JupyterHub domain (e.g., "lab.qbraid.com").
        username: JupyterHub username (email) for the WebSocket URL.
        token: JupyterHub API token.
        host_alias: SSH config host alias (default: qbraid-{short_domain}).
        ssh_user: SSH username inside the container (default: jovyan).
        identity_file: Path to SSH private key for authentication.

    Returns:
        SSHConfig object for the connection.
    """
    if host_alias is None:
        # Extract short name from domain (lab, lab-staging, etc.)
        short_name = hub_domain.split(".")[0]
        host_alias = f"qbraid-{short_name}"

    proxy_command = get_proxy_command(hub_domain, username, token)

    return SSHConfig(
        host=host_alias,
        hostname=hub_domain,
        user=ssh_user,
        port=22,  # Not actually used when ProxyCommand is set
        proxy_command=proxy_command,
        identity_file=identity_file,
    )


def add_sshd_proxy_config(
    hub_domain: str,
    username: str,
    token: str,
    host_alias: Optional[str] = None,
    ssh_user: str = "jovyan",
    identity_file: Optional[str] = None,
) -> SSHConfig:
    """Add SSH config entry for qBraid SSH proxy.

    This configures SSH to connect to a qBraid Lab pod through the
    jupyter-server-proxy SSH endpoint using WebSocket tunneling.

    Args:
        hub_domain: JupyterHub domain (e.g., "lab.qbraid.com").
        username: JupyterHub username (email).
        token: JupyterHub API token.
        host_alias: SSH config host alias.
        ssh_user: SSH username inside container (default: jovyan).
        identity_file: Path to SSH private key for authentication.

    Returns:
        SSHConfig object representing the entry.
    """
    config = generate_sshd_proxy_config(
        hub_domain, username, token, host_alias, ssh_user, identity_file
    )

    # Ensure include directive exists
    ensure_ssh_include()

    # Read existing config
    config_path = get_qbraid_ssh_config_path()
    existing_content = ""
    if config_path.exists():
        existing_content = config_path.read_text()

    # Check if host already exists
    if f"Host {config.host}" in existing_content:
        # Remove old entry
        lines = existing_content.split("\n")
        new_lines = []
        skip_until_next_host = False
        for line in lines:
            if line.startswith(f"Host {config.host}"):
                skip_until_next_host = True
                continue
            if skip_until_next_host and line.startswith("Host "):
                skip_until_next_host = False
            if not skip_until_next_host:
                new_lines.append(line)
        existing_content = "\n".join(new_lines)

    # Append new config
    new_content = existing_content.rstrip() + "\n\n" + config.to_ssh_config() + "\n"
    config_path.write_text(new_content.lstrip())
    config_path.chmod(0o600)

    return config


# =============================================================================
# SSH Key Management
# =============================================================================

# Default key path for qBraid SSH connections
QBRAID_SSH_KEY_NAME = "qbraid_ed25519"


def get_qbraid_key_path() -> Path:
    """Get path to qBraid SSH private key.

    Returns:
        Path to ~/.ssh/qbraid_ed25519
    """
    return Path.home() / ".ssh" / QBRAID_SSH_KEY_NAME


def generate_ssh_key(key_path: Optional[Path] = None, comment: str = "qbraid") -> Path:
    """Generate an Ed25519 SSH key pair for qBraid connections.

    If the key already exists, returns the existing path without overwriting.

    Args:
        key_path: Path for the private key (default: ~/.ssh/qbraid_ed25519).
        comment: Key comment (default: "qbraid").

    Returns:
        Path to the private key.

    Raises:
        RuntimeError: If ssh-keygen fails.
    """
    if key_path is None:
        key_path = get_qbraid_key_path()

    if key_path.exists():
        return key_path

    # Ensure .ssh directory exists
    key_path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)

    result = subprocess.run(
        [
            "ssh-keygen",
            "-t",
            "ed25519",
            "-f",
            str(key_path),
            "-N",
            "",  # No passphrase
            "-C",
            comment,
            "-q",
        ],
        capture_output=True,
        text=True,
        check=False,
    )

    if result.returncode != 0:
        raise RuntimeError(f"ssh-keygen failed: {result.stderr}")

    # Ensure correct permissions
    key_path.chmod(0o600)
    key_path.with_suffix(".pub").chmod(0o644)

    return key_path


def read_public_key(key_path: Optional[Path] = None) -> str:
    """Read the public key content.

    Args:
        key_path: Path to the private key (public key is at key_path.pub).

    Returns:
        Public key string.

    Raises:
        FileNotFoundError: If the public key doesn't exist.
    """
    if key_path is None:
        key_path = get_qbraid_key_path()

    pub_path = key_path.with_suffix(".pub")
    if not pub_path.exists():
        raise FileNotFoundError(f"Public key not found: {pub_path}")

    return pub_path.read_text().strip()


def parse_lab_url(url: str) -> dict[str, Optional[str]]:
    """Extract SSH connection parts from a lab/instance URL.

    Handles both legacy server URLs and BMA instance URLs of the form
    ``https://<host>/user/<username>/[<session>/]<ide>?token=<token>`` where
    ``<username>`` may itself contain a session segment (e.g.
    ``507f1f-kanavs/s-0e146b01``).

    Args:
        url: The lab URL (e.g. from ServerStatus.url or BMAInstance.url).

    Returns:
        Dict with keys ``hub_domain``, ``username``, ``token``, ``ide`` (any may
        be None if not present in the URL).
    """
    import re
    from urllib.parse import parse_qs, urlparse

    parsed = urlparse(url)
    token = parse_qs(parsed.query).get("token", [None])[0]
    hub_domain = parsed.hostname

    username: Optional[str] = None
    ide: Optional[str] = None
    match = re.search(r"/user/(.+?)/(lab|ssh|tree|vscode)(?:/|\?|$)", parsed.path)
    if match:
        username = match.group(1)
        ide = match.group(2)

    return {"hub_domain": hub_domain, "username": username, "token": token, "ide": ide}


def _get_ssh_key_api_url(hub_domain: str, username: str, ide: str = "lab") -> str:
    """Get the URL for the SSH key management API.

    For lab/jupyterlab/vscode pods, the key management API is accessible
    through jupyter-server-proxy at /user/<username>/qbraid-lab/ssh-keys.
    For SSH-only pods (ide="ssh"), it's at /user/<username>/ssh-keys.

    Args:
        hub_domain: JupyterHub domain.
        username: JupyterHub username.
        ide: IDE type. "ssh" uses /ssh-keys, everything else uses /qbraid-lab/ssh-keys.

    Returns:
        Full URL for the SSH key API endpoint.
    """
    if ide == "ssh":
        return f"https://{hub_domain}/user/{username}/ssh-keys"
    # lab, jupyterlab, vscode all use jupyter-server-proxy with qbraid-lab prefix
    return f"https://{hub_domain}/user/{username}/qbraid-lab/ssh-keys"


def register_public_key(
    hub_domain: str,
    username: str,
    token: str,
    public_key: str,
    ide: str = "lab",
) -> dict:
    """Register a public key with the running pod.

    Sends the public key to the pod's SSH key management API,
    which appends it to ~/.ssh/authorized_keys inside the container.

    Args:
        hub_domain: JupyterHub domain.
        username: JupyterHub username.
        token: JupyterHub API token.
        public_key: Public key string (e.g., "ssh-ed25519 AAAA... qbraid").
        ide: IDE type ("lab" or "ssh") to determine API path.

    Returns:
        API response dict (e.g., {"message": "key added", "count": 1}).

    Raises:
        RuntimeError: If the API call fails.
    """
    url = _get_ssh_key_api_url(hub_domain, username, ide=ide)
    headers: dict[str, str | bytes] = {
        "Authorization": f"token {token}",
        "Content-Type": "application/json",
    }

    resp = requests.post(url, headers=headers, json={"public_key": public_key}, timeout=30)

    if resp.status_code not in (200, 201):
        try:
            error = resp.json().get("error", resp.text)
        except Exception:
            error = resp.text
        raise RuntimeError(f"Failed to register SSH key: {error}")

    return resp.json()


def list_registered_keys(
    hub_domain: str,
    username: str,
    token: str,
    ide: str = "lab",
) -> list[str]:
    """List public keys registered with the running pod.

    Args:
        hub_domain: JupyterHub domain.
        username: JupyterHub username.
        token: JupyterHub API token.
        ide: IDE type ("lab" or "ssh") to determine API path.

    Returns:
        List of public key strings.
    """
    url = _get_ssh_key_api_url(hub_domain, username, ide=ide)
    headers: dict[str, str | bytes] = {"Authorization": f"token {token}"}

    resp = requests.get(url, headers=headers, timeout=30)

    if resp.status_code != 200:
        raise RuntimeError(f"Failed to list SSH keys: {resp.text}")

    return resp.json().get("keys", [])


def remove_registered_key(
    hub_domain: str,
    username: str,
    token: str,
    public_key: str,
    ide: str = "lab",
) -> dict:
    """Remove a public key from the running pod.

    Args:
        hub_domain: JupyterHub domain.
        username: JupyterHub username.
        token: JupyterHub API token.
        public_key: Public key string to remove.
        ide: IDE type ("lab" or "ssh") to determine API path.

    Returns:
        API response dict.
    """
    url = _get_ssh_key_api_url(hub_domain, username, ide=ide)
    headers: dict[str, str | bytes] = {
        "Authorization": f"token {token}",
        "Content-Type": "application/json",
    }

    resp = requests.delete(url, headers=headers, json={"public_key": public_key}, timeout=30)

    if resp.status_code not in (200, 204):
        try:
            error = resp.json().get("error", resp.text)
        except Exception:
            error = resp.text
        raise RuntimeError(f"Failed to remove SSH key: {error}")

    return resp.json()


# =============================================================================
# Main Setup Entry Point
# =============================================================================


def setup_qbraid_ssh(
    username: str,
    token: str,
    cluster_id: str = DEFAULT_CLUSTER_ID,
    host_alias: Optional[str] = None,
    key_path: Optional[Path] = None,
    register_key: bool = True,
    ide: str = "lab",
    hub_domain: Optional[str] = None,
) -> dict:
    """Set up SSH access to qBraid Lab.

    This is the main entry point for configuring SSH access. It:
    1. Generates an SSH key pair (if needed)
    2. Registers the public key with the pod
    3. Writes SSH config with ProxyCommand and IdentityFile

    Args:
        username: Your qBraid/JupyterHub username (email).
        token: Auth token (qBraid access token or JupyterHub API token).
        cluster_id: Cluster ID (e.g., "lab", "lab-v2-staging"). Used to derive hub domain
            if hub_domain is not provided.
        host_alias: SSH config alias (default: qbraid-{cluster_id}).
        key_path: Path to SSH private key (default: ~/.ssh/qbraid_ed25519).
        register_key: Whether to register the public key with the pod (default: True).
        ide: IDE type from profile. "ssh" uses /ssh-keys, everything else
             uses /qbraid-lab/ssh-keys.
        hub_domain: Explicit hub domain (e.g., "bma-staging.qbraid.com").
            If provided, takes precedence over cluster_id derivation.

    Returns:
        Dict with connection details and commands.

    Example:
        >>> result = setup_qbraid_ssh("user@example.com", "my-token", cluster_id="lab")
        >>> print(result["ssh_command"])
        'ssh qbraid-lab'
    """
    if hub_domain is None:
        hub_domain = get_hub_domain(cluster_id)

    # Step 1: Generate or locate SSH key
    if key_path is None:
        key_path = get_qbraid_key_path()

    key_generated = not key_path.exists()
    key_path = generate_ssh_key(key_path, comment=f"qbraid-{hub_domain}")

    # Step 2: Register public key with the pod (if not already registered)
    key_registered = False
    if register_key:
        public_key = read_public_key(key_path)
        try:
            existing_keys = list_registered_keys(hub_domain, username, token, ide=ide)
            # Check if our key is already registered (compare key content without comment)
            pub_key_parts = public_key.split()[:2]  # [type, key_data]
            already_registered = any(k.split()[:2] == pub_key_parts for k in existing_keys)
        except Exception:
            already_registered = False

        if not already_registered:
            register_public_key(hub_domain, username, token, public_key, ide=ide)
            key_registered = True

    # Step 3: Write SSH config with ProxyCommand and IdentityFile
    config = add_sshd_proxy_config(
        hub_domain=hub_domain,
        username=username,
        token=token,
        host_alias=host_alias,
        identity_file=str(key_path),
    )

    return {
        "host_alias": config.host,
        "ssh_command": f"ssh {config.host}",
        "sftp_command": f"sftp {config.host}",
        "vscode_command": f"code --remote ssh-remote+{config.host} /home/jovyan",
        "cursor_command": f"cursor --remote ssh-remote+{config.host} /home/jovyan",
        "config_file": str(get_qbraid_ssh_config_path()),
        "websocket_url": get_sshd_proxy_url(hub_domain, username),
        "identity_file": str(key_path),
        "key_generated": key_generated,
        "key_registered": key_registered,
    }


# =============================================================================
# CLI Entry Point for WebSocket Bridge
# =============================================================================


def _cli_bridge():
    """CLI entry point for WebSocket bridge (websocat replacement).

    Usage:
        python -m qbraid_core.services.compute.ssh bridge <url> [--token TOKEN]

    This is used as the ProxyCommand in SSH config to bridge stdin/stdout
    to a WebSocket endpoint (e.g., jupyter-sshd-proxy).
    """
    import argparse

    parser = argparse.ArgumentParser(description="WebSocket-to-stdio bridge (websocat replacement)")
    parser.add_argument("command", choices=["bridge"], help="Command to run")
    parser.add_argument("url", help="WebSocket URL to connect to")
    parser.add_argument("--token", help="Authorization token")
    parser.add_argument(
        "--ping-interval",
        type=float,
        default=30.0,
        help="Ping interval in seconds",
    )
    args = parser.parse_args()

    if args.command == "bridge":
        # Add authorization header to URL if token provided
        url = args.url
        if args.token:
            # For websockets library, we need to pass headers differently
            # We'll create a custom bridge that adds the auth header
            asyncio.run(_run_bridge_with_auth(url, args.token, args.ping_interval))
        else:
            asyncio.run(run_websocket_bridge(url, args.ping_interval))


async def _run_bridge_with_auth(url: str, token: str, ping_interval: float):
    """Run WebSocket bridge with authorization header."""
    if not WEBSOCKETS_AVAILABLE:
        print("Error: websockets package required", file=sys.stderr)
        sys.exit(1)

    headers = {"Authorization": f"token {token}"}

    try:
        async with ws_connect(
            url,
            additional_headers=headers,
            ping_interval=ping_interval,
        ) as ws:
            # Set up stdin reader
            loop = asyncio.get_event_loop()
            reader = asyncio.StreamReader()
            protocol = asyncio.StreamReaderProtocol(reader)
            await loop.connect_read_pipe(lambda: protocol, sys.stdin.buffer)

            async def read_stdin():
                try:
                    while True:
                        data = await reader.read(4096)
                        if not data:
                            break
                        await ws.send(data)
                except Exception:
                    pass

            async def write_stdout():
                try:
                    async for message in ws:
                        if isinstance(message, bytes):
                            sys.stdout.buffer.write(message)
                        else:
                            sys.stdout.write(message)
                        sys.stdout.buffer.flush()
                except Exception:
                    pass

            # Run both tasks
            stdin_task = asyncio.create_task(read_stdin())
            stdout_task = asyncio.create_task(write_stdout())

            _done, pending = await asyncio.wait(
                [stdin_task, stdout_task],
                return_when=asyncio.FIRST_COMPLETED,
            )

            for task in pending:
                task.cancel()

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    _cli_bridge()
